<h1>Import summary</h1><div class="card"><p>Status: <strong><?=H::e(ucwords($run['status']))?></strong></p><p>Detected: <?=(int)$run['total_detected']?> · Selected: <?=(int)$run['selected_count']?> · Imported: <?=(int)$run['imported_count']?> · Skipped: <?=(int)$run['skipped_count']?> · Duplicates: <?=(int)$run['duplicate_count']?> · Invalid: <?=(int)$run['invalid_count']?> · Failed: <?=(int)$run['failed_count']?></p><?php if($run['batch_id']): ?><a class="btn" href="/seller/product-batch/<?=(int)$run['batch_id']?>">Open resulting review batch</a><?php endif; ?></div>
<?php if(!$items):?><div class="card empty">No source products were recorded for this import.</div><?php else:?><div class="responsive-table"><table><tr><th>Source product</th><th>Result</th><th>Notes</th><th>Draft</th></tr><?php foreach($items as $item): $warnings=json_decode((string)($item['warnings']??'[]'),true); ?><tr><td><?=H::e($item['source_title'])?><br><small><?=H::e($item['source_key'])?></small></td><td><?=H::e(ucwords($item['result_status']))?></td><td><?=H::e(implode(' ',array_filter(array_merge((array)$warnings,[$item['error_message']??'']))))?></td><td><?php if($item['product_id']): ?><a href="/seller/product/<?=(int)$item['product_id']?>">Edit draft</a><?php endif; ?></td></tr><?php endforeach; ?></table></div><?php endif;?>
